import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ficha import *
T="EPISTAXIS"; N=7; KW=dict(strip=K)
note=lambda t: f'<div style="font-size:36px;line-height:1.4;color:{G}">{t}</div>'
rows=lambda *x: '<div style="display:flex;flex-direction:column;gap:22px">'+"".join(x)+'</div>'
paso=lambda i,t: kicker(f"TÉCNICA 02 · PASO {i} DE 5")+big(t,118,R)
P=[
page(1,N,T,f'<div style="font-size:40px;font-weight:800;letter-spacing:6px;color:{Y}">TÉCNICA 02</div>'+big("EPISTAXIS",200,"#FFFFFF",True)+big(f'DE LA COMPRESIÓN AL <span style="color:{Y}">TAPONAMIENTO</span>',112,"#FFFFFF")+'<div style="font-size:40px;font-weight:600;line-height:1.3;max-width:820px">Cinco pasos en orden y cuándo avisar a Otorrinolaringología. Con ficha final.</div>',cover=True,dark=True,**KW),
page(2,N,T,paso(1,"COMPRIME BIEN")+'<div style="font-size:50px;font-weight:800;line-height:1.2">Pinza firme del tercio inferior de la nariz (la parte blanda), 5 minutos o más, sin soltar</div>'+rows(line("Paciente sentado, con la cabeza inclinada hacia delante"),line("Antes, que se suene para expulsar los coágulos"))+note("Comprimir sobre el hueso no sirve: el sangrado anterior está en el tabique, por debajo."),**KW),
page(3,N,T,paso(2,"VASOCONSTRICTOR Y ANESTESIA")+rows(line("Algodón o lentina empapados en anestésico local con vasoconstrictor",True),line("Dentro de la fosa que sangra y vuelve a comprimir 5–10 min"),line("Prudencia con la adrenalina en pacientes con cardiopatía"))+note("Reduce el sangrado y deja la mucosa anestesiada para explorar y cauterizar."),**KW),
page(4,N,T,paso(3,"BUSCA EL PUNTO")+'<div style="font-size:50px;font-weight:800;line-height:1.2">Rinoscopia anterior con buena luz, tras retirar los coágulos</div>'+rows(row("Ves el punto","Sangrado anterior: cauteriza"),row("No lo ves","Tapona; sospecha origen posterior"))+note("Registra lo que agrava el sangrado: anticoagulantes, antiagregantes, trastornos de la coagulación, consumo intranasal de drogas."),**KW),
page(5,N,T,paso(4,"CAUTERIZA SOLO EL PUNTO")+rows(line("Nitrato de plata sobre la mucosa ya anestesiada",True),line("Solo en el punto que sangra o que sospechas"),f'<div style="border-top:4px solid {K};padding-top:22px;font-size:42px;font-weight:800;line-height:1.3;color:{R}">Nunca los dos lados del tabique a la vez: riesgo de perforación</div>'),**KW),
page(6,N,T,paso(5,"TAPONA")+'<div style="font-size:46px;font-weight:800;line-height:1.2">Taponamiento anterior si sigue sangrando o no localizas el punto</div>'+rows(line("Anticoagulado, antiagregado o con trastorno de la coagulación: material reabsorbible",True),line("Explica el tipo de taponamiento, cuándo se retira y los signos para volver"),line("Sangra pese al taponamiento: avisa a Otorrinolaringología")),**KW),
page(7,N,T,ficha_body("EPISTAXIS","Adulto",[("POSICIÓN","Sentado, cabeza hacia delante. Sonarse antes"),("1. COMPRIMIR","Tercio inferior de la nariz, firme y continuo, ≥ 5 min",True),("2. PREPARAR","Algodón con anestésico local y vasoconstrictor, 5–10 min"),("3. LOCALIZAR","Rinoscopia anterior. Punto visible: nitrato de plata, un solo lado"),("4. TAPONAR","Si persiste o no se ve el punto. Reabsorbible si toma antitrombóticos"),("AVISAR A ORL","Sangrado pese al taponamiento o sospecha de origen posterior",True),("ANTICOAGULADO","Sin riesgo vital: primero medidas locales; no revertir de entrada")],"Tunkel DE, et al. Guía AAO-HNS de epistaxis. Otolaryngol Head Neck Surg 2020;162(1 supl):S1-38",size=120,fs=29),ficha="02",fam="TÉCNICA",**KW),
]
render(P,sys.argv[1] if len(sys.argv)>1 else "out","tecnica-epistaxis")
